INSERT INTO prescriptions VALUES(151,23,1,'2023-24','FC26','optimal','RW',85,64,'w_wideplm','Build-Up',NULL,NULL,NULL,NULL,NULL,'실측 슬롯 x85 커널 코사인: w_wideplm/Build-Up 0.81 > wm_insidefwd/Balanced 0.79 > w_insidefwd/Roaming 0.75. 현 4-2-3-1 우측 등가역할=wm_insidefwd/Balanced. 서사(''다이렉트 스피드 위어'')보다 터치가 involved·인버티드 — off-ball 침투는 터치맵 미포착(실측>서사 캐비엇). 실측 최근접 현 선수: 아데예미 0.87(둘 다 인사이드 드리프트).',0);
