INSERT INTO prescriptions VALUES(153,24,1,'2024-25','FC26','optimal','ST',50,87,'st_advanced','Attack',NULL,NULL,NULL,NULL,NULL,'중앙 ST 풋프린트는 변별력 약함(실측 그리드 코사인은 왓킨스조차 st_false9 최고로 뽑음 — st_advanced 커널이 과전진). 선수간 실측 유사도: 기라시 0.95·왓킨스 0.90·브로베이 0.90. ''듀란형''은 히트맵이 아니라 능력치(PAC85+·PHY80+·파워/롱슛·인비하인드)로 정의. optimal 역할은 에메리 실사용(임팩트 서브·다이렉트·인비하인드·중앙고정)에 따라 st_advanced/Attack 지정.',0);
