INSERT INTO prescriptions VALUES(168,25,1,'2024-25','FC26','measured','LW/CF',34,68,'wm_insidefwd','Attack','X6223X6212323013310000000',NULL,NULL,NULL,NULL,'빌라 임대 45분+ 12경기(2025-02-15~04-22) 균등가중 통합 그리드(SofaScore API 814590, 2026-07-17 수집). 중심(34.0,68.4) 좌 하프스페이스 전진, 자기진영 점유 .145(좌측 수비면제 운용 증거). 스탯: xG .24·xA .25·kp 2.25·4골·평점 7.50. LM 슬롯 커널 최적 wm_insidefwd/Attack .895. 경기별 appearances 행은 24-25 matches 미적재로 생략 — 원 데이터는 SofaScore event별 재수집 가능(리포트 2026-07-17 참조).',0);
