INSERT INTO prescriptions VALUES(171,27,1,'2026-27','FC26','measured','RB',81.70000000000000284,46.60000000000000142,'','','00014000240002X0003900113',NULL,NULL,NULL,NULL,'25/26 RB 라이프치히 임대 우측 선발 4경기(≥45분: Magdeburg·Frankfurt·Union·Leverkusen)의 SofaScore 히트맵 균등가중 통합. tool orientation row0=공격/col0=좌. centroid tool_x81.7(우측)·tool_y46.6(딥). 우측 딥RB — 전진 빈도 낮음. 26/27 RB 뎁스 평가용. Source: SofaScore API /event/*/player/1152923/heatmap (2026-07-22).',0);
INSERT INTO prescriptions VALUES(172,28,1,'2026-27','FC26','measured','RM/AMR',75.90000000000000569,55.10000000000000142,'','','001251015X011261013600122',NULL,NULL,NULL,NULL,'25/26 웨스트브롬 임대 우측 선발 12경기의 SofaScore 히트맵 균등가중 통합(주 포지션). tool orientation row0=공격/col0=좌. centroid tool_x75.9(우측)·tool_y55.1(전진). 등록상 LM이나 실측 주력은 우측 인사이드윙/윙백. 26/27 스쿼드 평가용. Source: SofaScore API /event/*/player/996919/heatmap (2026-07-22).',0);
INSERT INTO prescriptions VALUES(173,28,1,'2026-27','FC26','measured:L','LW/AML',23.80000000000000071,56.60000000000000142,'','','64112X3210721008320031100',NULL,NULL,NULL,NULL,'25/26 웨스트브롬 임대 좌측 선발 4경기(1월 Middlesbrough·Norwich·Derby·Portsmouth)의 SofaScore 히트맵 균등가중 통합(부 포지션). tool orientation row0=공격/col0=좌. centroid tool_x23.8(좌측)·tool_y56.6(전진). 시즌 후반 좌측 전환 표본. Source: SofaScore API /event/*/player/996919/heatmap (2026-07-22).',0);
INSERT INTO prescriptions VALUES(174,18,1,'2024-25','FC26','measured:ST','ST',49,65,NULL,NULL,'47X5246555334756122100101',NULL,NULL,NULL,NULL,unistr('니스 베스트6 중 중앙 출전 3경기(앙제 8.7·브레스트 8.6·생테티엔 8.3) 통합. SofaScore 평균 y≈51.7(중앙), x≈65.3(전진). att-centre 24%가 최빈 존, 좌우 하프스페이스로 자유 드리프트(mid-left 18%). 3경기 4골3도움 xG평균 0.96. 게상이 "잘할 때"의 주 프로파일 — 중앙 스트라이커/세컨톱으로 좌측 하프스페이스 드리프트 자유가 있을 때 최고 산출. 표본 3경기로 그리드는 MEDIUM-HIGH\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.\u000a\u000a✅ **[2026-07-31 obs#108 — 방향 정정, obs#84 ⑥ 종결]** 파이프 제거(29자→25자) 후 남아 있던 **행 순서 의문을 DB 내부 교차검증으로 확정**했다. 행 순서가 규약(row0=공격 3분의 1)과 **역전**돼 있어 5행을 역순으로 뒤집었다(열 순서는 원래부터 정상 — 180° 회전이 아니라 순수 행 뒤집기). 근거: `tool_y`에서 예측되는 행 중심 대비 편차가 뒤집기 전 **0.63~1.48** → 뒤집은 후 **0.02~0.07**로, `player_role_map` 나머지 **87행의 편차 범위(중앙값 0.035 · 최대 0.231)** 에 정확히 들어온다. 반대로 다른 행을 뒤집으면 악화한다(대조: pid 13 0.23→0.83 · pid 23 0.13→1.40) — 즉 **게상 4행만 역전**이었다. tool 좌표 자체는 `player_match_positions.avg_x/avg_y`(SofaScore API·HIGH) 집계와 재현되므로 자(尺)가 신뢰된다. **SofaScore 원본 재수집은 불요**로 판단해 obs#84 ⑥의 "인용 전 재도출" 요구를 종결한다. ⚠️ 잔존 캐비앗 2건: ⓐ 니스 시절 행은 3백 경기 표본이라 `lineup_pos` 라벨 신뢰도가 낮다(obs#98) — **방향·평균좌표에는 영향 없고 슬롯 라벨 해석에만 걸린다.** ⓑ 25/26 빌라 행의 열 중심이 예측보다 0.30 낮아 좌우 폭 해석에는 이 오차를 병기할 것. 그는 26/27 스쿼드 밖(roster 2026-06-30 club=Crystal Palace)이라 현 프리셋에 영향이 없다.'),0);
