INSERT INTO prescriptions VALUES(176,18,1,'2025-26','FC26','measured','RM',79,58,NULL,NULL,'013440112X111360112601112',NULL,NULL,NULL,NULL,unistr('빌라 45분+ 15경기 중 우측 14경기 통합(좌측 1경기 제외, 포지션-순수 규칙). 평균 y≈21.5(니스 우측 26.6보다 5p 더 측면 고정), att-right 32%+mid-right 31%+def-right 16% = 우측 레인에만 79%. 니스 대비 att-centre 10%로 중앙 관여 반감, def-right 16%로 수비 부담 배증. 산출 붕괴: 평점 8.42→6.44(니스 베스트6 대비), 니스 시즌 전체 7.30 대비도 -0.86. 터치 39→29, xG 0.62→0.17, xA 0.44→0.02, 키패스 1.5→0.4. 에메리 4-2-3-1 우측 윙어는 측면 고정+수비 트래킹 임무 — 게상의 강점(중앙 연계·하프스페이스 드리프트·박스 침투)이 구조적으로 차단된 배치. 실측 결론: 부적응이 아니라 역할 미스매치\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.\u000a\u000a✅ **[2026-07-31 obs#108 — 방향 정정, obs#84 ⑥ 종결]** 파이프 제거(29자→25자) 후 남아 있던 **행 순서 의문을 DB 내부 교차검증으로 확정**했다. 행 순서가 규약(row0=공격 3분의 1)과 **역전**돼 있어 5행을 역순으로 뒤집었다(열 순서는 원래부터 정상 — 180° 회전이 아니라 순수 행 뒤집기). 근거: `tool_y`에서 예측되는 행 중심 대비 편차가 뒤집기 전 **0.63~1.48** → 뒤집은 후 **0.02~0.07**로, `player_role_map` 나머지 **87행의 편차 범위(중앙값 0.035 · 최대 0.231)** 에 정확히 들어온다. 반대로 다른 행을 뒤집으면 악화한다(대조: pid 13 0.23→0.83 · pid 23 0.13→1.40) — 즉 **게상 4행만 역전**이었다. tool 좌표 자체는 `player_match_positions.avg_x/avg_y`(SofaScore API·HIGH) 집계와 재현되므로 자(尺)가 신뢰된다. **SofaScore 원본 재수집은 불요**로 판단해 obs#84 ⑥의 "인용 전 재도출" 요구를 종결한다. ⚠️ 잔존 캐비앗 2건: ⓐ 니스 시절 행은 3백 경기 표본이라 `lineup_pos` 라벨 신뢰도가 낮다(obs#98) — **방향·평균좌표에는 영향 없고 슬롯 라벨 해석에만 걸린다.** ⓑ 25/26 빌라 행의 열 중심이 예측보다 0.30 낮아 좌우 폭 해석에는 이 오차를 병기할 것. 그는 26/27 스쿼드 밖(roster 2026-06-30 club=Crystal Palace)이라 현 프리셋에 영향이 없다.'),0);
INSERT INTO prescriptions VALUES(177,18,1,'2025-26','FC26','measured:CP-loan','CAM',40,62,NULL,NULL,'12311X7443324312211101100',NULL,NULL,NULL,NULL,unistr('팰리스 임대 45분+ 7경기 통합(글라스너 3-4-2-1의 좌측 10번/세컨톱). 평균 y≈60.6(중앙-좌측), x≈62.3. mid-left 24%+att-left 17%가 최빈 — 니스 measured:ST 프로파일(중앙+좌하프스페이스 드리프트)과 방향 일치. 즉 팰리스는 게상을 "맞는 역할"에 썼다. 그러나 산출은 부분 회복에 그침: 45분+ 평점 6.77, 경기당 xG 0.17·xA 0.05·키패스 0.14 — 빌라 우측(xG 0.17)과 동일 수준, 니스 베스트6(xG 0.62·xA 0.44)에는 크게 미달. 2골 모두 컨퍼런스리그(즈린스키)·PL 교체 18분(울버햄튼), PL 선발 경기 평점 6.2~6.5. 결론: 역할 교정만으로 니스 산출이 복원되지 않음 — 니스 24-25 폭발에는 리그 수준·xG 초과달성(10골/xG7.77) 요인이 겹쳐 있었다는 방증. 4/9 이후 무릎 부상 9경기 결장으로 표본 확장 불가\u000a⚠️ [2026-07-31 형식 정정] map25가 파이프 구분 29자(''00101|61221|…'')로 저장돼 있었다 — 툴의 decodeMap은 25자만 읽으므로 이 행은 NaN을 만들어 **모든 코사인 계산에서 무효**였다. 파이프만 제거해 25자로 정규화했다. ⚠️ **행 순서(방향)는 미검증**: 이 행의 기록된 툴 중심(y≈65.3=전진)과 그리드 행 중심(2.73)을 대조하면 **row0=자기진영**(프로젝트 규약 row0=최전방과 반대)일 가능성이 크다. 게상은 26/27 스쿼드 밖이라 현 프리셋에 영향이 없으나, **이 행을 인용하기 전에 SofaScore 원본에서 재도출할 것**.\u000a\u000a✅ **[2026-07-31 obs#108 — 방향 정정, obs#84 ⑥ 종결]** 파이프 제거(29자→25자) 후 남아 있던 **행 순서 의문을 DB 내부 교차검증으로 확정**했다. 행 순서가 규약(row0=공격 3분의 1)과 **역전**돼 있어 5행을 역순으로 뒤집었다(열 순서는 원래부터 정상 — 180° 회전이 아니라 순수 행 뒤집기). 근거: `tool_y`에서 예측되는 행 중심 대비 편차가 뒤집기 전 **0.63~1.48** → 뒤집은 후 **0.02~0.07**로, `player_role_map` 나머지 **87행의 편차 범위(중앙값 0.035 · 최대 0.231)** 에 정확히 들어온다. 반대로 다른 행을 뒤집으면 악화한다(대조: pid 13 0.23→0.83 · pid 23 0.13→1.40) — 즉 **게상 4행만 역전**이었다. tool 좌표 자체는 `player_match_positions.avg_x/avg_y`(SofaScore API·HIGH) 집계와 재현되므로 자(尺)가 신뢰된다. **SofaScore 원본 재수집은 불요**로 판단해 obs#84 ⑥의 "인용 전 재도출" 요구를 종결한다. ⚠️ 잔존 캐비앗 2건: ⓐ 니스 시절 행은 3백 경기 표본이라 `lineup_pos` 라벨 신뢰도가 낮다(obs#98) — **방향·평균좌표에는 영향 없고 슬롯 라벨 해석에만 걸린다.** ⓑ 25/26 빌라 행의 열 중심이 예측보다 0.30 낮아 좌우 폭 해석에는 이 오차를 병기할 것. 그는 26/27 스쿼드 밖(roster 2026-06-30 club=Crystal Palace)이라 현 프리셋에 영향이 없다.'),0);
INSERT INTO prescriptions VALUES(178,31,2,'2025-26','FC26','measured','GK',50,11,'gk_goalkeeper','Defend','0000000000000000010001X10',NULL,6,6.799999999999999823,NULL,'실측 6경기 평균 6.80. 중심(51.8,10.8). GK 커널 적합 gk_goalkeeper/Defend 0.961 > Balanced 0.953 > sweeper/Balanced 0.773 → 스위퍼형 아님. 자기진영 질량 1.00.',0);
INSERT INTO prescriptions VALUES(179,35,2,'2025-26','FC26','measured','LCB',31,35,'cb_bpd','Aggressive','0000023100661007X30045200',NULL,NULL,6.519999999999999574,NULL,'⭐ 실측이 포지션 서사를 정정: 6경기 평균 6.52, 중심(27.0,35.3). **LB(x=14) 최고 적합 fb_falseback/Balanced 0.717 < LCB(x=31) cb_bpd/Aggressive 0.930** → 쿠쿠렐라 후임 LB가 아니라 좌측 CB 프로필이다. 전방 0.12/자기진영 0.62.',0);
INSERT INTO prescriptions VALUES(180,33,2,'2025-26','FC26','measured','RCB',66,32,'cb_bpd','Aggressive','000000001101262023X400344',NULL,6,6.469999999999999752,NULL,'실측 6경기 평균 6.47, 중심(66.5,31.8). RCB cb_bpd/Aggressive **0.953** vs LCB 0.239 → **우측 전용**. 전방 0.05/자기진영 0.70 = 순수 수비형.',0);
INSERT INTO prescriptions VALUES(181,34,2,'2025-26','FC26','measured','RCB',66,38,'cb_bpd','Aggressive','0020002331137922X8X316440',NULL,3,NULL,NULL,'실측 3경기(45분+ 표본 부족) 평균 6.47, 중심(52.7,37.6). RCB 0.744 > LCB 0.665 — 중앙 성향이라 백3의 중앙 CB 후보. 전방 0.14/자기진영 0.59.',0);
INSERT INTO prescriptions VALUES(182,32,2,'2025-26','FC26','measured','RB',86,46,'fb_att_wb','Support','00015111390004X0015900147',NULL,6,6.400000000000000355,NULL,'실측 6경기 평균 6.40, 중심(81.5,46.3). RB fb_att_wb/Support 0.862 > wingback/Support 0.830. 전방 0.34/자기진영 0.44 = 균형형 전진 풀백. 알론소 체계의 "폭 독점 윙백" 요구에 부합하는 유일한 보유 우측 인원.',0);
INSERT INTO prescriptions VALUES(183,36,2,'2025-26','FC26','measured','LDM',50,45,'dm_dlp','Roaming','000001333116X411574101111',NULL,6,7.0,NULL,'실측 6경기 평균 7.00, 중심(47.6,44.5). **LDM(x=50) dm_dlp/Roaming 0.941** > RDM(x=61) 0.692 → 우측 피벗이 아니라 중앙 피벗. 전방 0.20/자기진영 0.40.',0);
INSERT INTO prescriptions VALUES(184,37,2,'2025-26','FC26','measured','LM',14,57,'wm_wideplm','Attack','311116X431386113522001000',NULL,6,7.280000000000000248,NULL,'⭐ 실측 6경기 평균 7.28(첼시 필드 최고), 중심(35.3,57.0) 좌측 편향. **LM(x=14) wm_wideplm/Attack 0.750 > LDM dm_dlp/Roaming 0.698 > CAM playmaker/Roaming 0.631** → 피벗 라벨보다 좌측 와이드 플레이메이커 형태에 가깝다. 전방 0.49/자기진영 0.21.',0);
INSERT INTO prescriptions VALUES(185,38,2,'2025-26','FC26','measured','RM',86,62,'wm_winger','Balanced','311264213X110191201410011',NULL,6,6.629999999999999894,NULL,'실측 6경기 평균 6.63, 중심(65.4,61.8). RM wm_winger/Balanced 0.875 > insidefwd/Balanced 0.847. LM 0.316 → 우측 전용. 전방 0.59/자기진영 0.20 = **터치라인형 윙어**(알론소 체계에 윙어 슬롯이 없다는 obs 모순의 실측 근거).',0);
INSERT INTO prescriptions VALUES(186,39,2,'2025-26','FC26','measured','RM',86,60,'wm_wideplm','Attack','11223225XX015640123200011',NULL,NULL,6.820000000000000284,NULL,'⭐⭐ 실측이 "CAM 10번" 라벨을 정정: 6경기 평균 6.82, 중심(65.0,59.9) **우측 편향**. **CAM(x=50) 최고 0.676(halfwinger/Balanced) < RM(x=86) wm_wideplm/Attack 0.845**. LM 0.152로 완전 부적합. 전방 0.59/자기진영 0.16 → 알론소의 2×10 중 **우측 축**.',0);
INSERT INTO prescriptions VALUES(187,40,2,'2025-26','FC26','measured','ST',50,61,'st_false9','Build-Up','243116X533232331212300110',NULL,NULL,6.919999999999999929,NULL,'⭐ 서사-실측 일치 사례: 6경기 평균 6.92, 중심(45.1,61.4). ST(x=50) st_false9/Build-Up 0.624 · **CAM 0.718(playmaker/Roaming)이 더 높다** → A1이 기록한 "내려오는 9번(dropping nine)" 서술을 실측이 지지. 전방 0.61/자기진영 0.18.',0);
INSERT INTO prescriptions VALUES(188,41,2,'2025-26','FC26','measured','RDM',61,52,'dm_dlp','Roaming','301170125901284002X800123',NULL,3,NULL,NULL,'실측 3경기(표본 부족) 평균 7.33(최고). 중심(73.3,52.3). **RDM dm_dlp/Roaming 0.772 > RB fb_inverted/Attack 0.692** → 인버티드 윙백/하이브리드. 알론소가 트렌트에게 준 "inverted role" 지시의 첼시 대응 인원 후보.',0);
INSERT INTO prescriptions VALUES(189,42,2,'2025-26','FC26','measured','RM',86,58,'wm_widemid','Support','01354013780003X0025910001',NULL,3,NULL,NULL,'실측 3경기(표본 부족) 평균 6.77, 중심(76.1,58.2). RM wm_widemid/Support 0.789 > winger/Balanced 0.746. 전방 0.51/자기진영 0.29 = 네투보다 복귀 성향이 큼.',0);
INSERT INTO prescriptions VALUES(190,13,2,'2026-27','FC26','measured','LM',14,56,'wm_insidefwd','Balanced','65321X9632564117410121100',NULL,NULL,NULL,NULL,'⭐ 빌라 실측 그리드를 첼시 행으로 이관(사용자 지시). 근거 데이터는 **아스톤 빌라 25/26 실측**(에메리 체제 LW/인버티드)이며 첼시 실측이 아니다. 커널 적합: LW(x=28) w_insidefwd/Balanced 0.778 > **LM(x=14) wm_insidefwd/Balanced 0.733** > CAM 0.664 > RM 0.178(부적합). 전방 0.58/자기진영 0.21. **알론소 지시와의 대조**: 그는 로저스를 "포켓 위치 — 스트라이커 근처, 우리 10번 근처"로 규정(1티어 구단 공식)했는데 실측은 CAM(0.664)보다 좌측 인사이드(0.778)에 가깝다 → 알론소가 요구하는 중앙화는 **실측상 아직 근거가 없는 변화**다. 팔머와의 실측 겹침은 0.465로 낮아 좌우 분리 공존은 가능(팔머 중심 x=65 우측 / 로저스 좌측).',0);
INSERT INTO prescriptions VALUES(191,43,3,'2025-26','FC26','measured','GK',50,11,'gk_goalkeeper','Defend','0000000000000000010001X30',NULL,6,6.799999999999999823,NULL,unistr('실측 6경기 평균 6.80, 중심(53.0,11.4). GK gk_goalkeeper/Defend 0.979 > Balanced 0.969 > sweeper 0.821 → 스위퍼형 아님.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **gk_goalkeeper/Defend 0.979** (차2 gk_goalkeeper/Balanced 0.969). 슬롯 x는 **정본 50**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
