INSERT INTO prescriptions VALUES(195,46,3,'2025-26','FC26','measured','RB',86,46,'fb_wingback','Support','00011010381125X0016700124',NULL,NULL,7.049999999999999823,NULL,unistr('⭐ 미드필더의 RB 전용 사례 실측. 6경기 평균 7.05, 중심(77.6,46.4). RB fb_wingback/Support 0.843 · fb_inverted/Build-Up 0.814 / **RDM(x=61) dm_dlp/Roaming 0.800** → 미드필드 드리프트 서술을 지지. 다만 전방 0.26/자기진영 0.39로 **구스토(0.34/0.44)·캐시(0.33/0.47)보다 공격 관여가 낮다** → 3티어의 "트렌트급" 서술은 실측이 지지하지 않는다(트렌트형은 전방 질량이 높아야 함). 인버티드 축 참고 표본.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **fb_wingback/Support 0.843** (차2 fb_att_wb/Support 0.807). 슬롯 x는 **정본 87**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(196,48,3,'2025-26','FC26','measured','RB',86,58,'fb_inverted','Attack','000680001X000170002500123',NULL,4,NULL,NULL,unistr('실측 4경기(표본 부족) 평균 6.42, 중심(85.8,58.3). RB **fb_inverted/Attack 0.905** · RM wm_insidefwd/Attack 0.875 → 풀백이 아니라 사실상 우측 공격 인원. 전방 0.54/자기진영 0.28 = 존스의 정반대. 같은 RB 슬롯에 두 유형이 공존.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **fb_att_wb/Support 0.867** (차2 fb_att_wb/Attack 0.845). 슬롯 x는 **정본 87**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(197,49,3,'2025-26','FC26','measured','LDM',50,49,'dm_dlp','Roaming','112113X594266632466514432',NULL,6,6.769999999999999574,NULL,unistr('실측 6경기 평균 6.77, 중심(52.9,48.6). **LDM(x=50) 0.782 > RDM(x=61) 0.677** → 중앙 피벗. 전방 0.38/자기진영 0.38 = 대칭형.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **dm_dlp/Roaming 0.689** (차2 dm_holding/Roaming 0.525). 슬롯 x는 **정본 38**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(198,50,3,'2025-26','FC26','measured','LDM',50,49,'dm_dlp','Roaming','00321377622X9614887211211',NULL,5,6.639999999999999681,NULL,unistr('실측 5경기 평균 6.64, 중심(47.1,49.2). LDM dm_dlp/Roaming **0.909** > RDM 0.639. 전방 0.33/자기진영 0.37. ⚠️ 그라베르베르흐와 동일 슬롯·동일 역할 최적 → 더블 피벗 두 축이 실측상 분화되지 않았다(슬롯 배분은 별도 판단 필요).\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **dm_dlp/Roaming 0.890** (차2 dm_dlp/Build-Up 0.690). 슬롯 x는 **정본 38**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(199,51,3,'2025-26','FC26','measured','RDM',61,57,'dm_dlp','Roaming','41324345XX237861326610110',NULL,NULL,NULL,NULL,unistr('⭐ 다중 슬롯 순회 실측(RM/RDM/CAM 36경기). 평균 7.02, 중심(59.8,57.0). **RDM dm_dlp/Roaming 0.812 > RM wm_wideplm/Attack 0.730 > CAM halfwinger/Balanced 0.673** → 세 라벨 중 실측 최적은 RDM. 전방 0.49/자기진영 0.23.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **dm_dlp/Roaming 0.674** (차2 dm_boxcrasher/Balanced 0.569). 슬롯 x는 **정본 62**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(200,52,3,'2025-26','FC26','measured','CAM',50,59,'cam_halfwinger','Balanced','120425857X443564223210100',NULL,5,7.0,NULL,unistr('실측 5경기 평균 7.00, 중심(54.1,58.7). CAM cam_halfwinger/Balanced 0.785 > classic10/Versatile 0.711. RM 0.687. 전방 0.54/자기진영 0.19. £100m 영입 대비 부진 시즌이라는 서사와 달리 평점은 필드 상위.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **cam_halfwinger/Balanced 0.785** (차2 cam_classic10/Versatile 0.711). 슬롯 x는 **정본 50**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(201,53,3,'2025-26','FC26','measured','LM',14,64,'wm_insidefwd','Balanced','56831X8674768332323200100',NULL,6,6.519999999999999574,NULL,unistr('실측 6경기 평균 6.52, 중심(42.5,63.6). **LM 0.648 · CAM 0.686 · ST 0.579** — 세 슬롯 모두 0.7 미만으로 어디에도 강하게 맞지 않는다(LM↔ST 겸업의 대가). 전방 0.59/자기진영 0.13.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **wm_insidefwd/Balanced 0.675** (차2 wm_insidefwd/Attack 0.652). 슬롯 x는 **정본 14**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(202,54,3,'2025-26','FC26','measured','RM',86,71,'wm_insidefwd','Attack','011480003X000240001100000',NULL,5,NULL,NULL,unistr('⭐⭐ 실측 5경기 평균 **7.56**(리버풀 최고), 중심(82.6,71.3). RM **wm_insidefwd/Attack 0.961** — 이 프로젝트가 측정한 전 후보 중 최고치(하지무사 0.923·카타모 0.915 상회). 침투 서명 **전방 0.77/자기진영 0.06**은 하지무사(0.76/0.14)를 넘는다. ⚠️ 2026-07-01 FA로 이탈 — **obs#38 "뒷공간 반복 침투 빠른 우측 윙어" 브리프의 실측 원형(archetype)으로 보존**. 빌라 우측 후보 평가 시 이 그리드를 상한 기준선으로 쓸 수 있다.\u000a\u000a🔄 **[2026-07-31 obs#120 — 신커널 재산출]** 이 행의 적합값은 **폐기된 옛 `placedMap`**(미러+정수 시프트 합성) 산물이었고 obs#93·#94의 교체 이후 **정정 표기가 없던 12행 중 하나**다. 신기준(EA 정본 변형 선택) 재산출: **wm_winger/Attack 0.910** (차2 wm_winger/Balanced 0.775). 슬롯 x는 **정본 85**(obs#82 ①) — 이 행에 저장된 x는 옛 표를 따랐다. ⚠️ 값만 재산출한 것이고 **인선·처방 판정은 하지 않았다** — 리버풀은 26/27 처방이 없고(RCB·RM·LB 주인 미정) 8/23 뉴캐슬 원정 실측 대기다. ⚠️ 이 그리드는 **25/26 슬롯 체제** 표본이고 이라올라 전술이 아니다(불변규칙 7).'),0);
INSERT INTO prescriptions VALUES(203,31,2,'2026-27','FC26','projected','GK',50,11,'gk_goalkeeper','Defend',NULL,NULL,NULL,NULL,NULL,'실측 최적 그대로(0.961). 알론소 원칙의 "GK가 압박 시 +1 수적우위 제공"(obs#44)은 gk_sweeper를 함의하나 실측 적합 0.773으로 낮아 채택하지 않음 — 서사보다 실측 우선(불변규칙 #3).',0);
INSERT INTO prescriptions VALUES(204,35,2,'2026-27','FC26','projected','LCB',31,36,'cb_bpd','Aggressive',NULL,NULL,NULL,NULL,NULL,'실측 LCB 0.930. A2 조사의 "쿠쿠렐라 후임 LB" 제안을 실측이 반박(LB 0.717) — 그는 좌측 CB다. 백3 좌측 = 볼플레잉 CB(obs#58의 "볼플레잉 CB 2 + 강력한 CB 1" 중 하나).',0);
INSERT INTO prescriptions VALUES(205,34,2,'2026-27','FC26','projected','CCB',50,34,'cb_bpd','Aggressive',NULL,NULL,NULL,NULL,NULL,'⭐ **CCB 신설의 근거 인선**. 실측 CCB 0.873 > RCB 0.744 > LCB 0.665 — 중심 x 52.7로 정확히 중앙. 캐비앗: 45분+ 표본 3경기.',0);
INSERT INTO prescriptions VALUES(206,33,2,'2026-27','FC26','projected','RCB',66,32,'cb_bpd','Aggressive',NULL,NULL,NULL,NULL,NULL,'실측 RCB 0.953(CCB 0.669·LCB 0.424) = 우측 전용. 전방 0.05/자기진영 0.70으로 백3 중 가장 순수한 수비형 → obs#58의 "강력한 CB 1" 역할.',0);
INSERT INTO prescriptions VALUES(207,32,2,'2026-27','FC26','projected','RB',86,46,'fb_att_wb','Support',NULL,NULL,NULL,NULL,NULL,'실측 RB fb_att_wb/Support 0.862. 알론소 체계에서 폭을 독점하는 윙백(obs#46: 윙백은 크로서가 아니라 득점자, 프림퐁형). 전방 0.34/자기진영 0.44 = 전방 4인 중 유일한 수비 질량 공급자.',0);
INSERT INTO prescriptions VALUES(208,36,2,'2026-27','FC26','projected','LDM',50,45,'dm_dlp','Roaming',NULL,NULL,NULL,NULL,NULL,'실측 LDM 0.941(RDM 0.692). 알론소 원칙의 "피벗이 백라인 옆까지 내려와 압박 유인 후 관통"(obs#44)에 정합 — 자기진영 0.40.',0);
INSERT INTO prescriptions VALUES(209,41,2,'2026-27','FC26','projected','RDM',61,52,'dm_dlp','Roaming',NULL,NULL,NULL,NULL,NULL,'실측 RDM 0.772로 우측 피벗 유일 적합 인원(엔소는 RDM 0.361로 부적합). 알론소가 트렌트에게 준 "inverted role" 지시(obs#57)의 첼시 대응. ⚠️ 표본 3경기 — 이 처방의 가장 약한 칸.',0);
INSERT INTO prescriptions VALUES(210,13,2,'2026-27','FC26','projected','LM',14,56,'wm_insidefwd','Balanced',NULL,NULL,NULL,NULL,NULL,'좌측 10번. 실측 LM 0.733(CAM 0.664·RM 0.178). ⚠️ 두 겹의 캐비앗: ① 그리드가 빌라 25/26(에메리 체제) 것 ② **엔소가 LM 0.750으로 근소 우위**라 실측만 보면 엔소가 이 칸의 1순위다. 로저스를 두는 근거는 알론소의 명시 지시(obs#59, 1티어 구단 공식)와 £117m 영입 사실이며, 실측 근거는 아니다.',0);
INSERT INTO prescriptions VALUES(211,39,2,'2026-27','FC26','projected','RM',86,60,'wm_wideplm','Attack',NULL,NULL,NULL,NULL,NULL,'우측 10번. 실측 RM 0.845 ≫ CAM 0.676, LM 0.152. ⭐ 알론소는 그를 "포켓·10번 근처"로 말했지만 실측 중심 x=65는 **우측 편향**이다. 로저스와의 실측 겹침 0.465(낮음) → 좌우 분리 공존은 구조적으로 가능.',0);
INSERT INTO prescriptions VALUES(212,40,2,'2026-27','FC26','projected','ST',50,61,'st_false9','Build-Up',NULL,NULL,NULL,NULL,NULL,'실측 ST 0.624이나 CAM 0.718이 더 높다 = obs#59의 "내려오는 9번" 서사를 실측이 지지. false9/Build-Up이 그 성향에 가장 가까운 ST 역할. ⚠️ 로저스와 실측 겹침 **0.863(최고)** — 좌측 10번과 9번이 같은 공간을 쓴다. 알론소 체계의 실질 리스크 지점.',0);
INSERT INTO prescriptions VALUES(213,21,1,'2025-26','FC26','measured','CM',50.20000000000000284,53,NULL,NULL,'111112768114X601444200101',NULL,NULL,NULL,NULL,'[2026-08-05 신규 수집] SofaScore pid 98435. 최근 6경기(45분+·히트포인트 15+ 충족): PL 05-24 맨시티(86분·37pt)·05-15 리버풀(45분·40pt)·05-10 번리(80분·54pt)·05-03 토트넘(85분·42pt)·04-19 선더랜드(70분·34pt)·04-12 노팅엄(77분·44pt). 04-25 풀럼(16분)·03-04 첼시(27분)·02-27 울브스(30분) 등은 45분 미달로 제외. 경기당 정규화 후 균등가중. 평균 평점 6.52(5.7~7.0). ⚠️ 프리시즌 친선 4경기(07-21 월솔·07-25 포르투·07-28 레알소시에다드·08-01 인도네시아XI)는 SofaScore가 선수별 statistics/heatmap을 제공하지 않는다(전건 HTTP 404) — 따라서 "프리시즌 LDM 기용"은 실측으로 직접 확인 불가이고, 이 행은 25/26 공식전 기준선이다. 자체검증: 경기별 평균중심(tool 50.2, 53.0)과 그리드 질량중심(51.1, 53.9) 일치. 대역 분해 공격3rd 7%·공격미들 35%·미들 32%·수비미들 22%·수비3rd 4%, 열 7%·24%·34%·28%·8%로 좌우 대칭 중앙형. 경기별 tool_x가 43.8~61.5로 흔들려 좌우 고정이 아니다(좌우 스왑 로테이션).',0);
INSERT INTO prescriptions VALUES(214,21,1,'2025-26','FC26','role','RDM',62,42,'dm_dlp','Roaming','111112768114X601444200101',NULL,NULL,NULL,NULL,'[2026-08-05] 슬롯별 전수 채점(fc26-heatmap.html roleOptions 정의 재사용, 회귀검증: 카마라 .656·오나나 .805 재현). RDM(x=62) dm_dlp/Roaming 0.836 — 2위 dm_dlp/Build-Up .575 대비 Δ.260으로 단독. LDM(x=38)도 dm_dlp/Roaming 0.798(Δ.302). CAM(x=50) cam_playmaker/Build-Up 0.803(Δ.043)이 근접 3위. LM .441·RM .444로 와이드는 부적합. ⚠️ 깊이만 보면 오판한다 — 바클리 tool_y 53.0은 피봇 3인(오나나 41.2·카마라 44.9·틸레만스 46.9)보다 6~12p 높고 로저스 55.5·부엔디아 56.3에 가까워 "DM 대역이 아니다"로 읽히지만, 커널 채점은 반대다. dm_dlp/Roaming이 중앙 3개 열로 퍼지는 광역 커널이라 바클리의 넓고 중앙 대칭인 분포를 잘 담기 때문이다. 즉 판정 근거는 평균 좌표가 아니라 분포 형태다. [스쿼드 내 서열] LDM: 틸레만스 .858 > 오나나 .835 > 바클리 .798 > 카마라 .656. RDM: 카마라 .850 > 바클리 .836 > 오나나 .805 > 틸레만스 .714. CAM: 바클리 .803이 스쿼드 1위(맥긴 .641·틸레만스 .621·부엔디아 .592·카마라 .592·오나나 .579) — 마진 .162로 압도적. [해석] 프리시즌 LDM 기용은 실측이 지지한다(.798, 스쿼드 3위). 다만 그의 최적은 RDM(.836)이고 CAM에서는 스쿼드 최고다. 상호 코사인 틸레만스 .846·카마라 .806·오나나 .805로 피봇 3인과 프로파일이 유사해 대체 가능하고, 맥긴 .448·보가르드 .596과는 다르다. [맥락] 틸레만스가 맨유로 CONFIRMED 이적, 오나나 무릎 장기 이탈, 카마라는 1월 십자인대 파열 후 08-04 BG빠툼전에서 복귀 첫 출전 — 피봇 자원이 고갈된 상태가 프리시즌 LDM 기용의 배경으로 정합적이다. ⚠️ 등급 캐비앗: 표본 6경기이고 SofaScore position 라벨이 전건 일반값 "M"이라 경기별 LDM/RDM/CAM 구분은 불가하다. 슬롯 판정은 커널 적합도에 의존하며 라벨 근거가 아니다. 또 유출 이력 있음 — 07-27 리포트에 코번트리와 어드밴스드 협상(GiveMeSport/Football Insider, 2티어권, 램파드 커넥션+PSR 임금정리)이 기록돼 1티어 확인 대기 상태였다. SofaScore 소속은 2026-08-05 현재 Aston Villa로 확인된다. [2026-08-05 CAM 전수 열거 추가] CAM(x=50) 10개 역할×포커스 전수: cam_playmaker/Build-Up 0.803 → Roaming 0.760 → Balanced 0.755 → cam_classic10/Wide 0.602 → Attack 0.597 → Versatile 0.561 → cam_halfwinger/Roaming 0.406 → Attack 0.405 → Balanced 0.404 → cam_shadow/Attack 0.260. **CAM 기용 시 최적은 cam_playmaker/Build-Up**(1위, 2위와 Δ0.043으로 동점구간 밖 단독). playmaker 계열이 상위 3위를 독점하고 classic10이 .56~.60, halfwinger가 .40, shadow가 .26으로 계단식으로 떨어진다 — 즉 "내려와서 배급하는 10번"이고 "박스로 침투하는 10번(shadow)"이 아니다. Build-Up이 Roaming을 이긴 것은 그의 분포가 공격미들 35%·미들 32%·수비미들 22%로 뒤쪽까지 걸쳐 있기 때문이다. [스쿼드 CAM 서열 재확인] 바클리 .803 > 맥긴 .641 > 틸레만스 .621 > 부엔디아 .592 = 카마라 .592 > 오나나 .579 > 보가르드 .351 — 마진 .162로 스쿼드 최고 CAM 적합자다. 로저스 첼시 이적(£117m)으로 10번 자리가 빈 상황과 맞물린다. [프리시즌 라인업 확인 2026-08-05] SofaScore 라인업으로 바클리는 친선 5경기 중 4경기(07-21 월솔·07-25 포르투·07-28 레알소시에다드·08-01 인도네시아XI) 선발, 08-04 BG빠툼만 결장. 즉 방출 대상이 아니라 주력으로 쓰이고 있다. 다만 SofaScore 라인업 포지션 라벨이 G/D/M/F 4단계뿐이어서 LDM·RDM·CAM 구분은 불가하다.',0);
